import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import {
  useBffData,
  usePageFilterData,
  usePageFilterStatus,
  useSubFilters,
} from 'hooks';
import { LineBarChartsSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

import { StyledCommercialResultsContent } from '../../CommercialResults.styles';
import { createBaseWaterfallConfig } from '../../config/createBaseWaterfallConfig';
import {
  COMMERCIAL_RESULTS_LINE_BAR_CHARTS_BFF_ID,
  COMMERCIAL_RESULTS_LINE_BAR_CHARTS_COMPONENT_ID,
  COMMERCIAL_RESULTS_PAGE_NAME,
} from '../../constants';
import {
  DataView,
  useCommercialResultsFullPageEmptyState,
} from '../../hooks/useCommercialResultsFullPageEmptyState/useCommercialResultsFullPageEmptyState';
import { useKpiDrillDownData } from '../../hooks/useKpiDrillDownData/useKpiDrillDownData';
import { getCommercialResultsLineBarChartFilteredByDisplayValue } from '../../utils/getCommercialResultsLineBarChartFilteredBy';
import { getCommercialResultsSubFilters } from '../../utils/getCommercialResultsSubFilters';
import { CommercialResultsEmptyState } from '../CommercialResultsEmptyState/CommercialResultsEmptyState';
import { BigNumbersSection } from '../Sections/BigNumbersSection/BigNumbersSection';
import { LineBarChartsSection } from '../Sections/Charts/LineBarChartSection/LineBarChartSection';
import { WaterfallSection } from '../Sections/Charts/WaterfallSection/WaterfallSection';
import { ExploreFurtherSection } from '../Sections/ExploreFurtherSection/ExploreFurtherSection';
import { PerformanceSection } from '../Sections/PerformanceSection';

const SKELETON_PROPS = {
  height: '308px',
  width: '100%',
  length: 1,
  borderRadius: 'none' as const,
};

export const KpiDrillDown = () => {
  const { applied, bigNumbersData, waterfallData, performanceInfo, config } =
    useKpiDrillDownData();

  const { formatMessage } = useIntl();
  const { activeSubFilters } = useSubFilters();
  const { status } = usePageFilterStatus(COMMERCIAL_RESULTS_PAGE_NAME);
  const { dataFilters } = usePageFilterData(COMMERCIAL_RESULTS_PAGE_NAME);
  const shouldSkipRequest =
    status !== 'loaded' || !applied?.zone || !applied?.country;

  const subFilters = useMemo(
    () => getCommercialResultsSubFilters(applied, activeSubFilters),
    [applied, activeSubFilters],
  );

  const lineBarBffData = useBffData({
    id: COMMERCIAL_RESULTS_LINE_BAR_CHARTS_BFF_ID,
    kpiGroup: config.kpiGroup,
    subFilters,
    skipMainFilters: false,
    skipRequest: shouldSkipRequest,
  });

  const lineBarChartsData = useMemo(
    () =>
      lineBarBffData.data?.[COMMERCIAL_RESULTS_LINE_BAR_CHARTS_COMPONENT_ID] as
        | LineBarChartsSectionData
        | null
        | undefined,
    [lineBarBffData.data, activeSubFilters],
  );

  const lineBarChartTitle = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.CommercialResults.performance.lineBarChart.title',
      }),
    [formatMessage],
  );

  const lineBarChartSubtitle = useMemo(
    () => ({
      prefix: formatMessage({
        id: 'ValueCreation.CommercialResults.performance.lineBarChart.subtitlePrefix',
      }),
      value: getCommercialResultsLineBarChartFilteredByDisplayValue(
        subFilters,
        dataFilters,
        applied,
      ),
    }),
    [formatMessage, subFilters, dataFilters, applied],
  );

  const waterfallConfig = useMemo(
    () => createBaseWaterfallConfig(config.kpiName),
    [config.kpiName],
  );

  const views = useMemo<DataView[]>(
    () => [
      {
        loading: bigNumbersData.loading,
        error: bigNumbersData.error,
        isEmpty:
          !bigNumbersData.bigNumbersData ||
          bigNumbersData.bigNumbersData?.every(
            (item) => item?.data?.length === 0,
          ),
      },
      {
        loading: waterfallData.loading,
        error: waterfallData.error,
        isEmpty:
          !waterfallData.waterfallData || !!waterfallData.waterfallData.empty,
      },
      {
        loading: lineBarBffData.loading,
        error: lineBarBffData.error,
        isEmpty: !lineBarChartsData || !!lineBarChartsData.empty,
      },
    ],
    [
      bigNumbersData.loading,
      bigNumbersData.error,
      bigNumbersData.bigNumbersData,
      waterfallData.loading,
      waterfallData.error,
      waterfallData.waterfallData,
      lineBarBffData.loading,
      lineBarBffData.error,
      lineBarChartsData,
    ],
  );

  const { showFullPageEmpty } = useCommercialResultsFullPageEmptyState(views);

  if (showFullPageEmpty) {
    return <CommercialResultsEmptyState />;
  }

  return (
    <StyledCommercialResultsContent>
      <BigNumbersSection data={bigNumbersData} skeletonProps={SKELETON_PROPS} />
      <PerformanceSection
        title={performanceInfo.performanceSection}
        tooltip={performanceInfo.tooltip}
      >
        <WaterfallSection
          config={waterfallConfig}
          title={waterfallData.title}
          measure={config.measure}
          data={waterfallData.waterfallData}
          loading={waterfallData.loading}
          error={waterfallData.error}
        />
        <LineBarChartsSection
          title={lineBarChartTitle}
          subtitle={lineBarChartSubtitle}
          measure={config.measure}
          data={lineBarChartsData}
          loading={lineBarBffData.loading}
          error={lineBarBffData.error}
          showLineDataLabels
          skeletonProps={SKELETON_PROPS}
        />
      </PerformanceSection>
      <ExploreFurtherSection />
    </StyledCommercialResultsContent>
  );
};
